#!/bin/sh
# Generated by StackToIT from execution-plan.json. StackToIT has not run this script and runs none.
# Read-only checks of what the draft wrote, after the apply: a workload is rolled out and has pods (kubectl rollout status, kubectl get pods), a load balancer
# answers (a request with curl). It creates, changes and deletes nothing. The same commands are listed in execution/verify/checks.md.
# Needs: kubectl and the kubeconfig of the cluster in KUBECONFIG, the namespace the manifests were applied into in NAMESPACE, tofu for the load balancers' addresses, curl.
# A manifest the draft holds back (replicas: 0) has no pod until the start step of its service scales it: run this after that step.
# Exit status: 0 when every check held, 1 when one did not.
set -u

here=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
tf="$here/../../terraform"
failures=0
stackit_tofu() {
  if [ -n "${STACKIT_BACKEND_ACCESS_KEY_ID:-}" ]; then
    ( AWS_ACCESS_KEY_ID="$STACKIT_BACKEND_ACCESS_KEY_ID"; AWS_SECRET_ACCESS_KEY="${STACKIT_BACKEND_SECRET_ACCESS_KEY:-}"; export AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY; tofu "$@" )
  else
    tofu "$@"
  fi
}
run() {
  printf '%s\n' "+ $*"
  "$@" || { failures=$((failures + 1)); printf '%s\n' "FAILED: $*" >&2; }
}
[ -n "${NAMESPACE:-}" ] || { printf '%s\n' 'NAMESPACE is not set: the namespace the manifests were applied into.' >&2; exit 2; }
[ -n "${KUBECONFIG:-}" ] || { printf '%s\n' 'KUBECONFIG is not set: the kubeconfig file of the cluster.' >&2; exit 2; }

# terraform/kubernetes/carts/manifests.yaml: Deployment carts
run kubectl -n "$NAMESPACE" rollout status 'deployment/carts' --timeout=300s
run kubectl -n "$NAMESPACE" get pods -l 'app.kubernetes.io/name=carts'

# terraform/kubernetes/catalog/manifests.yaml: Deployment catalog
run kubectl -n "$NAMESPACE" rollout status 'deployment/catalog' --timeout=300s
run kubectl -n "$NAMESPACE" get pods -l 'app.kubernetes.io/name=catalog'

# terraform/kubernetes/checkout/manifests.yaml: Deployment checkout
run kubectl -n "$NAMESPACE" rollout status 'deployment/checkout' --timeout=300s
run kubectl -n "$NAMESPACE" get pods -l 'app.kubernetes.io/name=checkout'

# terraform/kubernetes/orders/manifests.yaml: Deployment orders
run kubectl -n "$NAMESPACE" rollout status 'deployment/orders' --timeout=300s
run kubectl -n "$NAMESPACE" get pods -l 'app.kubernetes.io/name=orders'

# terraform/kubernetes/ui/manifests.yaml: Deployment ui
run kubectl -n "$NAMESPACE" rollout status 'deployment/ui' --timeout=300s
run kubectl -n "$NAMESPACE" get pods -l 'app.kubernetes.io/name=ui'

# stackit_application_load_balancer.retail_app_ecs_alb_this
address=$(stackit_tofu -chdir="$tf" output -raw 'retail_app_ecs_alb_this_external_address' 2>/dev/null) || address=''
if [ -z "$address" ]; then
  failures=$((failures + 1)); printf '%s\n' 'FAILED: no address for stackit_application_load_balancer.retail_app_ecs_alb_this (is it applied?)' >&2
else
  printf '%s\n' "+ curl http://$address/"
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 20 "http://$address/") || code=000
  case "$code" in
    2??) printf '%s\n' "$code" ;;
    *) failures=$((failures + 1)); printf '%s\n' "FAILED: stackit_application_load_balancer.retail_app_ecs_alb_this answered $code, expected 2xx (a 503 shortly after the apply: the targets are not healthy yet, ask again)" >&2 ;;
  esac
fi

if [ "$failures" -gt 0 ]; then printf '%s\n' "$failures check(s) failed." >&2; exit 1; fi
printf '%s\n' 'Every check held.'
